package com.nexus.web; import java.util.*; import com.nexus.domain.*; import com.nexus.domain.Rules.*;
public final class Views{private Views(){} public static Map<String,Object> map(Object... values){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)m.put((String)values[i],values[i+1]);return m;}
 public static Map<String,Object> user(Account a){var m=map("id",a.id,"name",a.name,"email",a.email,"role",a.role(),"enabled",a.enabled);if(a instanceof Technician t)m.putAll(map("skills",new java.util.LinkedHashMap<>(t.skills),"capacity",t.capacity,"available",t.available));return m;}
 public static Map<String,Object> service(ITService s){return map("id",s.id,"name",s.name,"criticality",s.criticality,"providers",new java.util.LinkedHashSet<>(s.providers));}
 public static Map<String,Object> incident(Incident i,Role role){return incidentView(i,role,true);}
 public static Map<String,Object> incidentSummary(Incident i,Role role){return incidentView(i,role,false);}
 private static Map<String,Object> incidentView(Incident i,Role role,boolean detail){var m=map("id",i.id,"title",i.title,"description",i.description,"locationCode",i.locationCode,"locationName",i.locationCode==null?null:CampusCatalog.require(i.locationCode).name(),"locationNote",i.locationNote,"status",i.status(),"priority",i.priority,"impact",i.impact,"urgency",i.urgency,"criticality",i.criticality,"score",i.impact*i.urgency*i.criticality,"reporter",i.reporter.name,"reporterId",i.reporter.id,"technician",i.technician==null?null:i.technician.name,"technicianId",i.technician==null?null:i.technician.id,"service",i.service.name,"serviceId",i.service.id,"category",i.category.name,"categoryId",i.category.id,"createdAt",i.createdAt,"responseDue",i.responseDue,"resolutionDue",i.resolutionDue,"acknowledgedAt",i.acknowledgedAt,"resolvedAt",i.resolvedAt,"closedAt",i.closedAt,"responseBreach",i.responseBreach,"resolutionBreach",i.resolutionBreach,"responseWarning",i.responseWarning,"resolutionWarning",i.resolutionWarning,"escalated",i.escalated,"resolution",i.resolution,"rating",i.rating,"feedback",i.feedback);if(detail&&role!=Role.EMPLOYEE)m.putAll(map("related",new java.util.LinkedHashSet<>(i.related),"assignmentEvidence",role==Role.ADMINISTRATOR?i.assignmentEvidence:null));return m;}
}
